declare(strict_types=1);

/**
 * lote25.php — Limpieza: la documentación que mentía y el mapa que no preguntaba.
 *
 * REQUIERE el lote 24 aplicado.
 *
 * Sin migración y sin cambios de servidor.
 *
 * 1. `docs/testing.md` DECÍA QUE LA SUITE NUNCA SE HABÍA EJECUTADO
 *
 * Se ejecutó el 25 de agosto y quedó en 433 verdes. El documento llevaba desde
 * entonces afirmando lo contrario, y encima decía que los ficheros sin ejecutar
 * «llevan un aviso en su cabecera» — ninguno lo lleva ya. Reescrito con lo que
 * pasa de verdad:
 *
 *   • Que la suite se ejecutó, cuándo, y con qué resultado.
 *   • Qué se aprendió de aquel arranque: de 119 fallos, UNO era de la
 *     aplicación. El resto eran de las pruebas mismas.
 *   • Los ONCE ficheros de pruebas añadidos después, que no he ejecutado nunca,
 *     con sus nombres.
 *   • Qué sí se comprueba antes de entregar cada lote: `php -l`, `tsc`, paridad
 *     de diccionarios, y desde el lote 18 el DDL de cada migración contra un
 *     MySQL 8.0.46 real con el esquema entero cargado.
 *   • Una sección nueva sobre por qué todas las migraciones son reanudables, y
 *     la restricción de MySQL que costó un despliegue: una clave foránea con
 *     ON DELETE CASCADE no puede estar sobre una columna base de una columna
 *     generada STORED.
 *
 * 2. EL MAPA DE LA OFICINA YA NO LLAMA A GOOGLE SOLO
 *
 * El marco lo sirve Google, y con `loading="lazy"` se cargaba al hacer scroll:
 * en la práctica, Google recibía la IP de casi todo el que abriera la página de
 * contacto, hubiera querido ver el mapa o no.
 *
 * Ahora hay que pulsar. Quien quiere el mapa lo pide y lo ve; quien venía a
 * leer un teléfono no le entrega su IP a un tercero sin enterarse. Debajo queda
 * el enlace de siempre para abrirlo fuera.
 *
 * Tu política de privacidad YA declara «mapas y rutas» entre los subencargados,
 * así que esto no tapaba un hueco: reduce cuánta gente entra en ese supuesto.
 * Es criterio de ingeniería, no asesoramiento legal — la redacción del documento
 * sigue siendo cosa tuya y de tu abogado.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote25.php            # aplica
 *     php lote25.php --dry-run  # dice qué haría y no toca nada
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);
$hechos = []; $saltados = []; $errores = [];

function ruta(string $rel): string { global $raiz; return $raiz.DIRECTORY_SEPARATOR.$rel; }

function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (is_file($destino) && file_get_contents($destino) === $contenido) { $saltados[] = "= {$rel}"; return; }
    $existia = is_file($destino);
    if ($dry) { $hechos[] = ($existia ? '~ ' : '+ ').$rel; return; }
    $dir = dirname($destino);
    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) { $errores[] = "no se pudo crear el directorio {$dir}"; return; }
    if (file_put_contents($destino, $contenido) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados. Si el resultado ya está, se salta; si el texto de
 * partida está una sola vez, se sustituye; si no, se aborta el fichero entero
 * sin escribir — un anclaje que no encaja significa que el fichero no es el que
 * este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (! is_file($destino)) { $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?"; return; }
    $texto = file_get_contents($destino); $aplicados = 0; $yaEstaban = 0;
    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) { $yaEstaban++; continue; }
        $veces = substr_count($texto, $antes);
        if ($veces !== 1) { $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero."; return; }
        $texto = str_replace($antes, $despues, $texto); $aplicados++;
    }
    if ($aplicados === 0) { $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)"; return; }
    if ($dry) { $hechos[] = "~ {$rel} ({$aplicados} trozo(s))"; return; }
    if (file_put_contents($destino, $texto) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

