/* ── Parte ───────────────────────────────────────────────────────────────── */

echo $dry ? "SIMULACIÓN (no se escribió nada)\n\n" : "lote25 — documentación y mapa\n\n";
foreach ($hechos as $l) { echo "  {$l}\n"; }
if ($saltados !== []) { echo "\n  ya estaba:\n"; foreach ($saltados as $l) { echo "    {$l}\n"; } }
if ($errores !== []) {
    echo "\nERRORES:\n";
    foreach ($errores as $l) { echo "  ! {$l}\n"; }
    echo "\nNada de lo que falló se escribió a medias.\n";
